//! Closed original BQ067. Ordinary effects apply to the same live owned core
//! recipients as BQ049; reading rest counters does not target the core zone.
use crate::{catalog,engine::RuleResult,model::*,rules::*};
use serde::{Serialize,Deserialize};
use std::collections::BTreeSet;
pub(crate) const ID:&str="BQ067";
pub(crate) const KEY:&str="bq067-core-barrier";
fn same<T:Serialize>(a:&T,b:&T)->bool{serde_json::to_value(a).unwrap()==serde_json::to_value(b).unwrap()}
pub(crate) fn definition()->Definition{let mut d=crate::rules::attachment_definition(target(Zone::Society,EntityKind::Any,Relation::ControlledByActor,Range::Anywhere));let mut a=ability(KEY,"支付1名誉并牺牲拟态：本方场上核心获得本回合屏障",Timing::Fast,vec![Cost::BQ067Honor,Cost::SacrificeSource],vec![],vec![Op::BQ067Barrier],None);a.activation_only=true;d.abilities.push(a);d.modifiers.push(StaticModifier::BQ067CoreDefense);d}
pub(crate) fn related(a:&AbilitySpec)->bool{a.key.starts_with("bq067-")||a.costs.iter().any(|c|matches!(c,Cost::BQ067Honor))||a.ops.iter().any(|o|matches!(o,Op::BQ067Barrier))}
pub(crate) fn validate_ability(id:&str,a:&AbilitySpec)->RuleResult<()>{if id!=ID||!definition().abilities.iter().any(|s|same(s,a)){return Err("拟态须保留本方秘社、名誉1和牺牲费用".into());}Ok(())}
pub(crate) fn validate_definition(id:&str,d:&Definition)->RuleResult<()>{if(id==ID||d.abilities.iter().any(related)||d.modifiers.iter().any(|m|matches!(m,StaticModifier::BQ067CoreDefense)))&&(id!=ID||!same(d,&definition())){return Err("拟态定义不可删改或移植".into());}Ok(())}
pub(crate) fn validate_action(c:&Card,a:&Action)->RuleResult<()>{if c.definition!=ID{return Ok(());}let expected=match a.kind.as_str(){"asset"=>Action{card_id:a.card_id.clone(),..Action::new("asset")},"play"=>{if a.ability_id.as_deref().is_some_and(|id|id!="attach"){return Err("拟态只能结附本人秘社".into());}Action{card_id:a.card_id.clone(),target_id:a.target_id.clone(),ability_id:a.ability_id.clone(),..Action::new("play")}},"activate"=>Action{card_id:a.card_id.clone(),ability_id:Some(KEY.into()),..Action::new("activate")},_=>return Err("拟态不支持该操作".into())};if *a!=expected{return Err("拟态操作不能夹带额外目标或费用载荷".into());}Ok(())}
fn relevant(f:&ResolutionFrame)->bool{f.source.card.definition==ID||f.ability_key.starts_with("bq067-")||f.steps.iter().any(|s|matches!(s.op,Op::BQ067Barrier))||f.already_paid.iter().any(|p|matches!(p,PaidCost::BQ067Honor{..}))}
#[derive(Clone,Debug,Serialize,Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Grant{pub frame:Box<ResolutionFrame>,pub recipient:Card,pub turn:u32}
impl Game {
 fn bq067_core(&self,c:&Card,actor:usize)->bool{!c.face_down&&c.controller==actor&&c.owner==actor&&self.board(&c.id).is_some_and(|(_,v)|v==c)&&self.selected_core_card(c)}
 pub(crate) fn bq067_defense(&self,c:&Card)->u32{let actor=c.controller;if actor>=self.players.len()||self.players[actor].eliminated||!self.bq067_core(c,actor){return 0;}let n=self.attachments.iter().filter(|a|a.card.definition==ID&&!a.card.face_down&&a.card.controller==actor&&a.host_id==format!("society:p{actor}")&&self.attachment_host_valid(a)).count()as u32;let rest=self.core_zones.iter().find(|z|z.owner==actor&&z.definition==c.definition).map_or(0,|z|z.rest);n.saturating_mul(1u32.saturating_add(rest))}
 pub(crate) fn bq067_pay(&mut self,actor:usize,s:&SourceSnapshot,a:&AbilitySpec)->RuleResult<PaidCost>{validate_ability(&s.card.definition,a)?;if a.key!=KEY||actor>=self.players.len()||s.card.face_down||s.card.controller!=actor||!self.attachments.iter().any(|v|v.card==s.card&&v.host_id==format!("society:p{actor}")&&self.attachment_host_valid(v)){return Err("拟态须由本人实际秘社附属支付".into());}let before=self.players[actor].honor;self.players[actor].honor=before.checked_sub(1).ok_or("名誉不足，资产不能替代")?;Ok(PaidCost::BQ067Honor{before})}
 pub(crate) fn validate_bq067_frame(&self,f:&ResolutionFrame)->RuleResult<()>{if !relevant(f){return Ok(());}self.validate_resource_frame(f)?;let s=&f.source;let c=&s.card;let a=definition().abilities.into_iter().find(|a|a.key==f.ability_key).ok_or("未知拟态能力")?;
 if c.definition!=ID||c.face_down||f.actor>=self.players.len()||c.owner>=self.players.len()||c.controller!=f.actor||!self.mystic_instance_number(&c.id).zip(self.mystic_instance_number(&f.frame_id)).is_some_and(|(c,f)|c<f)||s.region.is_some()||s.source_region_instance.is_some()||s.play_source.is_some()||s.death_echo.is_some()||s.observed_death.is_some()||s.observed_exposure.is_some()||s.observed_mobility_grant.is_some()||f.chosen_region.is_some()||f.cursor>f.steps.len()||f.cursor==0&&!matches!(f.guard,GuardState::Unchecked|GuardState::Accepted|GuardState::Cancelled)||f.cursor>0&&!matches!(f.guard,GuardState::Accepted)||!same(&f.steps,&a.ops.iter().map(|op|Step{context:f.actor,op:op.clone()}).collect::<Vec<_>>())||f.targets.len()!=a.targets.len(){return Err("拟态来源、程序或阶段损坏".into());}self.mobility_immutable_identity(c)?;
 if f.ability_key=="attach"{if s.attachment_host_instance.is_some()||!matches!(f.already_paid.as_slice(),[PaidCost::Assets(ids)]if f.money_units(0)<=2&&ids.iter().collect::<BTreeSet<_>>().len()==ids.len())||f.targets[0].id!=format!("society:p{}",f.actor)||!same(&f.targets[0].spec,&a.targets[0])||!f.targets[0].public.valid{return Err("拟态必须付费结附本人秘社".into());}}
 else if s.attachment_host_instance.as_deref()!=Some(format!("society:p{}",f.actor).as_str())||!f.resource_payments.is_empty()||!matches!(f.already_paid.as_slice(),[PaidCost::BQ067Honor{before},PaidCost::Sacrificed{old_instance,controller,owner}]if *before>=1&&old_instance==&c.id&&*controller==f.actor&&*owner==c.owner)||self.batch3_physical_cards().any(|v|v.id==c.id){return Err("拟态必须真实支付1名誉并牺牲原附属".into());}Ok(())}
 pub(crate) fn bq067_grant(&mut self,f:&ResolutionFrame)->RuleResult<()>{self.validate_bq067_frame(f)?;if f.ability_key!=KEY||f.cursor!=1||!matches!(f.guard,GuardState::Accepted){return Err("拟态屏障必须来自原结算步骤".into());}if self.players[f.actor].eliminated{return Ok(());}let recipients=self.regions.iter().flat_map(|r|&r.cards).filter(|c|self.bq067_core(c,f.actor)).cloned().collect::<Vec<_>>();for c in recipients{self.bq067_grants.push(Grant{frame:Box::new(f.clone()),recipient:c,turn:self.turn});}Ok(())}
 pub(crate) fn bq067_barrier(&self,c:&Card)->bool{!c.face_down&&self.board(&c.id).is_some()&&self.bq067_grants.iter().any(|g|g.turn==self.turn&&g.recipient.id==c.id)}
 pub(crate) fn validate_bq067_state(&self)->RuleResult<()>{let mut grants=BTreeSet::new();for g in &self.bq067_grants{self.validate_bq067_frame(&g.frame)?;let c=&g.recipient;if g.turn!=self.turn||g.frame.ability_key!=KEY||g.frame.cursor!=1||!matches!(g.frame.guard,GuardState::Accepted)||c.face_down||c.owner!=g.frame.actor||c.controller!=g.frame.actor||!self.mystic_instance_valid(&c.id)||!self.core_zones.iter().any(|z|z.owner==c.owner&&z.definition==c.definition)||!grants.insert((&g.frame.frame_id,&c.id)){return Err("拟态屏障原接收者、期限或唯一性损坏".into());}self.mobility_immutable_identity(c)?;}
 let mut seen=BTreeSet::new();let mut check=|f:&ResolutionFrame|->RuleResult<()>{self.validate_bq067_frame(f)?;if relevant(f)&&(self.bq067_grants.iter().any(|g|g.frame.frame_id==f.frame_id)||!seen.insert(f.frame_id.clone())){return Err("拟态同帧重复续体".into());}Ok(())};
 for i in &self.stack{if i.card.as_ref().is_some_and(|c|c.definition==ID)||i.frame.as_ref().is_some_and(relevant){let f=i.frame.as_ref().ok_or("拟态堆叠缺帧")?;check(f)?;if f.source.card.definition!=ID||f.cursor!=0||!matches!(f.guard,GuardState::Unchecked)||i.id!=f.frame_id||i.controller!=f.actor||i.reveal||i.deploy_region.is_some()||i.target!=f.targets.first().map(|t|t.id.clone())||i.card.is_some()!=(f.ability_key=="attach")||i.card.as_ref().is_some_and(|c|!self.pack_a_transaction_matches(f,c)){return Err("拟态实际堆叠外壳损坏".into());}}}
 for e in &self.effects{match e{Effect::Frame{frame:f}=>check(f)?,Effect::Declare{declaration:d}if d.source.card.definition==ID||related(&d.ability)=>return Err("拟态没有触发声明".into()),_=>{}}}if self.pending.as_ref().is_some_and(|p|match &p.resolution{ChoiceResolution::Frame{frame,..}=>relevant(frame),ChoiceResolution::Declare{declaration:d,..}=>d.source.card.definition==ID||related(&d.ability),_=>false}){return Err("拟态不含结算中待选".into());}Ok(())}
}
